VALUES (16, 'learn', 'Why Breathing Matters', 'Understanding why breathing matters matters to us and the world.', 'Understanding why breathing matters matters to us and the world.', '🌬️', 'general', '/generated-visuals/day-016/thumbnail.png', '[{"id":"day016-hook-001","phase_key":"hook","phase_index":0,"script":"Welcome to Day 16! Today we are exploring: Why Breathing Matters. Understanding why breathing matters matters to us and the world.","kelly_pose":"welcome","kelly_emotion":"curious","options":null,"visual_url":null},{"id":"day016-wisdom-001","phase_key":"wisdom","phase_index":1,"script":"Understanding why breathing matters matters to us and the world.","kelly_pose":"warm","kelly_emotion":"gentle","options":null,"visual_url":null},{"id":"day016-outro-001","phase_key":"outro","phase_index":2,"script":"That is today lesson! See you tomorrow for more learning adventures. Stay curious!","kelly_pose":"wave","kelly_emotion":"happy","options":null,"visual_url":null}]'::jsonb, '{"2-5":{"persona":"Playful Friend","phases":{"hook":"Hi little friend! Today we are learning about why breathing matters!","wisdom":"Understanding why breathing matters matters to us and the world.","outro":"Great job learning today! See you tomorrow!"}},"6-12":{"persona":"Cool Big Sister","phases":{"hook":"Hey curious one! Ready to discover something cool about why breathing matters?","wisdom":"Understanding why breathing matters matters to us and the world.","outro":"You are getting smarter every day. See you tomorrow!"}},"13-17":{"persona":"Smart Mentor","phases":{"hook":"Let us explore: Why Breathing Matters. Here is what you need to know.","wisdom":"Understanding why breathing matters matters to us and the world.","outro":"That is the real stuff. See you tomorrow."}},"18-35":{"persona":"Equal Partner","phases":{"hook":"Today topic: Why Breathing Matters. Let us break it down.","wisdom":"Understanding why breathing matters matters to us and the world.","outro":"Knowledge that makes a difference. See you tomorrow."}},"36-60":{"persona":"Respectful Guide","phases":{"hook":"Today we explore Why Breathing Matters - a subject worth understanding.","wisdom":"Understanding why breathing matters matters to us and the world.","outro":"Wisdom worth carrying forward. Until tomorrow."}},"61-102":{"persona":"Honored Equal","phases":{"hook":"Today we reflect on: Why Breathing Matters. A timeless subject.","wisdom":"Understanding why breathing matters matters to us and the world.","outro":"Until we meet again. Take care."}}}'::jsonb, 'approved', 'v3.0-skeleton', 'day-016-complete.js')
